std::mt19937 rng(std::random_device{}());
std::uniform_real_distribution<double> dist(-1.0, 1.0);
int intersections = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    Point3d direction(dist(rng), dist(rng), dist(rng));
    if (direction == Point3d(0, 0, 0)) continue;
    Ray3d ray(p, direction);
    std::vector<AABB_tree::Intersection_and_primitive_id> intersections_list;
    tree.all_intersections(ray, std::back_inserter(intersections_list));
    int count = 0;
    for (const auto& intersection : intersections_list) {
        if (intersection.first.type() == typeid(Point_3)) {
            count++;
        }
    }
    intersections += count % 2;
}
return intersections % 2 != 0;

